// === Tab: NPartcl ===
class NPartcl {

	constructor(x, y) {
		this.x = x;
		this.y = y;
		this.nx = x;
		this.ny = y;
		this.stop = false;
		this.clr = lerpColor(color("white"), color("deeppink"), random());
	}

	update(hills, t = 0) {
		this.x = this.nx;
		this.y = this.ny;

		const nx = this.x / width * multi;
		const ny = this.y / height * multi;
		const ns = noise(nx, ny, t)
		const vec = createVector(disti/5, 0);
		let ang = ns*TAU*4;
		vec.rotate(ang);

		this.nx = this.x + vec.x;
		this.ny = this.y + vec.y;

		if (random() < 0.01) this.stop = true;
		if (this.nx < 0 || this.nx > width) this.stop = true;
		if (this.ny < 0 || this.ny > height) this.stop = true;
	}

	draw() {
		stroke(this.clr);
		if (random()<0.76) line(this.x, this.y, this.nx, this.ny);
	}

}

