	description: 'Changes zoom multiplier of the noise field'
});

let particles, hills;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("standard noise field");
	strokeWeight(2);
	stroke("deeppink");
	noFill();
	background("navy");

	particles = [];
	for (let y = 0; y < height; y += disti) {
		for (let x = 0; x < width; x += disti) {
			if (random()<0.05) particles.push(new NPartcl(x, y));
		}		
	}

	hills = [];
	for (let i = 0; i < 10; i++) hills.push({x: random(width), y: random(height), z: random(1, 10)})
}

function draw() {
	background("#00008004");

	const t = millis()/1000;

	stroke("cyan")
	for (const h of hills) {
		circle(h.x, h.y, 10 * h.z)
	}

	for (const p of particles) {
		p.update(hills);
		p.draw();
	}

	particles = particles.filter((p) => !p.stop);

	particles.push(new NPartcl(random(~~(width/disti)) * disti, random(~~(height/disti)) * disti));

	// if (frameCount % 100 === 0) console.log(particles.length);
}

